import re
from datetime import date
from decimal import Decimal

from .errors import ParseError
from .models import Movement, Order, Product
from .shelves import first_below_zero

WS = " \t"

TAX_RATES = ("standard", "reduced", "zero")

_SKU_RE = re.compile(r"[A-Za-z]{2,4}-[0-9]{3}")
_PRICE_RE = re.compile(r"[0-9]+(\.[0-9]{1,2})?")
_DIGITS_RE = re.compile(r"[0-9]+")
_QUANTITY_RE = re.compile(r"[+-]?[0-9]+")
_DATE_RE = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})")
_ORDER_ID_RE = re.compile(r"[Ss][Oo]-[0-9]+")
_MOVEMENT_RE = re.compile(
    r"[ \t]*([^ \t]+)[ \t]+([^ \t]+)[ \t]+([^ \t]+)(.*)", re.DOTALL
)
_FIELD_SPLIT_RE = re.compile(r"[ \t]+")
_MIN_PRICE = Decimal("0.01")


def iter_lines(text):
    """Yield ``(line_number, line)`` for every line that carries data."""
    if text.startswith("﻿"):
        text = text[1:]
    for number, raw in enumerate(text.split("\n"), 1):
        if raw.endswith("\r"):
            raw = raw[:-1]
        body = raw.strip(WS)
        if not body or body.startswith("#"):
            continue
        yield number, raw


def parse_date(text):
    """Return a ``datetime.date`` for ``YYYY-MM-DD`` text, else ``None``."""
    match = _DATE_RE.fullmatch(text)
    if not match:
        return None
    try:
        return date(int(match.group(1)), int(match.group(2)), int(match.group(3)))
    except ValueError:
        return None


def _whole_number(number, text, what):
    try:
        return int(text)
    except ValueError:  # absurdly long digit strings
        raise ParseError(number, "%s %r is too large" % (what, text[:20]))


def _sku(number, text, catalog):
    if not _SKU_RE.fullmatch(text) or text.upper() not in catalog:
        raise _usage_error("wrong number of arguments for %s" % command)
    date_at = {"receive": 0, "ship": 0, "fulfil": 1}.get(command)
    if date_at is not None and parse_date(request.args[date_at]) is None:
        raise _usage_error("bad date %r (want a real YYYY-MM-DD date)" % request.args[date_at])
    return request


# ----------------------------------------------------------------------- files


def _read(folder, name, required):
    path = os.path.join(folder, name)
    try:
        with open(path, "rb") as handle:
            data = handle.read()
    except FileNotFoundError:
        if required:
            raise _Exit(2, "%s: file not found in %s" % (name, folder))
        return ""
    except OSError as error:
        raise _Exit(2, "%s: cannot read: %s" % (name, error.strerror or error))
    try:
        return data.decode("utf-8-sig")
    except UnicodeDecodeError:
        raise _Exit(2, "%s: not valid UTF-8" % name)


def _parse(name, function, *args):
    try:
        return function(*args)
    except ParseError as error:
        raise _Exit(1, "%s: %s" % (name, error))


class _Data:
    pass


def _load(request):
    command = request.command
    if not os.path.isdir(request.dir):
        raise _Exit(2, "%s: not a folder" % request.dir)
    texts = {"catalog.txt": _read(request.dir, "catalog.txt", True)}
    if command in _NEEDS_MOVEMENTS:
        texts["movements.txt"] = _read(request.dir, "movements.txt", False)
    if command in _NEEDS_ORDERS:
        texts["orders.txt"] = _read(request.dir, "orders.txt", False)
    data = _Data()
    data.dir = request.dir
    data.catalog = _parse("catalog.txt", parse_catalog, texts["catalog.txt"])
    data.movements = None
